      function numericChoiceValues(correct, candidates) {
        const values = [correct];
        candidates.forEach((value) => {
          if (values.length < 4 && Number.isInteger(value) && !values.includes(value)) {
            values.push(value);
          }
        });
        let delta = 1;
        while (values.length < 4) {
          [correct + delta, correct - delta].forEach(
            (value) => {
              if (values.length < 4 && !values.includes(value)) {
                values.push(value);
              }
            }
          );
          delta += 1;
        }
        return values;
      }
      function shuffledChoices(texts, correctIndex) {
        const entries = texts.map((text, index) => ({
          text,
          correct: index === correctIndex
        }));
        for (let index = entries.length - 1; index > 0; index -= 1) {
          const swap = randomInteger(0, index);
          [entries[index], entries[swap]] = [
            entries[swap],
            entries[index]
          ];
        }
        const keyed = entries.map((entry, index) => ({
          ...entry,
          key: String.fromCharCode(65 + index)
        }));
        return {
          choices: keyed.map(({ key, text }) => ({
            key,
            text
          })),
          answer: keyed.find(
            (entry) => entry.correct
          ).key
        };
      }
